Module: lin. Use suite name agent_lin. Write the file test_lin.c.

Header mlmw/lin.h (the specification):
```c
/* LIN 2.x helpers: protected identifier and frame checksum. */
#ifndef MLMW_LIN_H
#define MLMW_LIN_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define MLMW_LIN_ID_MASTER_REQ 0x3Cu
#define MLMW_LIN_ID_SLAVE_RESP 0x3Du

/* Protected identifier for a 6-bit frame id (bits above 5 are ignored).
 * P0 = ID0 ^ ID1 ^ ID2 ^ ID4, P1 = !(ID1 ^ ID3 ^ ID4 ^ ID5). */
uint8_t mlmw_lin_pid(uint8_t id);

/* True if both parity bits of a received PID are correct. */
bool mlmw_lin_pid_valid(uint8_t pid);

/* Checksum byte: 8-bit sum with carry wrap-around, inverted.
 * enhanced = include the PID (LIN 2.x). Diagnostic frames 0x3C and 0x3D
 * always use the classic checksum, whatever 'enhanced' says. */
uint8_t mlmw_lin_checksum(uint8_t pid, const uint8_t *data, size_t len, bool enhanced);

#endif
```

Implementation mlmw/src/lin.c:
```c
#include "mlmw/lin.h"

uint8_t mlmw_lin_pid(uint8_t id)
{
	uint8_t i = id & 0x3Fu;
	uint8_t p0 = ((i >> 0) ^ (i >> 1) ^ (i >> 2) ^ (i >> 4)) & 1u;
	uint8_t p1 = (~((i >> 1) ^ (i >> 3) ^ (i >> 4) ^ (i >> 5))) & 1u;

	return (uint8_t)(i | (p0 << 6) | (p1 << 7));
}

bool mlmw_lin_pid_valid(uint8_t pid)
{
	return mlmw_lin_pid(pid & 0x3Fu) == pid;
}

uint8_t mlmw_lin_checksum(uint8_t pid, const uint8_t *data, size_t len, bool enhanced)
{
	uint16_t sum = 0;
	uint8_t id = pid & 0x3Fu;

	if (enhanced && id != MLMW_LIN_ID_MASTER_REQ && id != MLMW_LIN_ID_SLAVE_RESP) {
		sum = pid;
	}
	for (size_t k = 0; k < len; k++) {
		sum += data[k];
		if (sum > 0xFFu) {
			sum = (uint16_t)(sum - 0xFFu);
		}
	}
	return (uint8_t)(~sum);
}
```

```c
#include "mlmw_test.h"
#include "mlmw/lin.h"
#include <string.h>

ZTEST(agent_lin, test_mlmw_lin_pid)
{
	uint8_t id = 0x24;
	uint8_t expected_pid = 0x24;
	uint8_t pid = mlmw_lin_pid(id);
	EXPEC_EQ(pid, expected_pid);
}

ZTEST(agent_lin, test_mlmw_lin_pid_with_parity)
{
	uint8_t id = 0x12;
	uint8_t expected_pid = 0x12 | (1 << 6) | (0 << 7);
	uint8_t pid = mlmw_lin_pid(id);
	EXPEC_EQ(pid, expected_pid);
}

ZTEST(agent_lin, test_mlmw_lin_pid_with_parity_2)
{
	uint8_t id = 0x3F;
	uint8_t expected_pid = 0x3F | (1 << 6) | (1 << 7);
	uint8_t pid = mlmw_lin_pid(id);
	EXPEC_EQ(pid, expected_pid);
}

ZTEST(agent_lin, test_mlmw_lin_pid_valid)
{
	uint8_t pid = 0x24;
	EXPEC_TRUE(mlmw_lin_pid_valid(pid));
}

ZTEST(agent_lin, test_mlmw_lin_pid_valid_with_parity)
{
	uint8_t pid = 0x12 | (1 << 6) | (0 << 7);
	EXPEC_TRUE(mlmw_lin_pid_valid(pid));
}

ZTEST(agent_lin, test_mlmw_lin_pid_valid_with_parity_2)
{
	uint8_t pid = 0x3F | (1 << 6) | (1 << 7);
	EXPEC_TRUE(mlmw_lin_pid_valid(pid));
}

ZTEST(agent_lin, test_mlmw_lin_pid_invalid)
{
	uint8_t pid = 0x25;
	EXPEC_FALSE(mlmw_lin_pid_valid(pid));
}

ZTEST(agent_lin, test_mlmw_lin_checksum)
{
	uint8_t pid = 0x24;
	uint8_t data[] = {0x01, 0x02, 0x03};
	uint8_t expected_checksum = 0x06;
	uint8_t checksum = mlmw_lin_checksum(pid, data, 3, false);
	EXPEC_EQ(checksum, expected_checksum);
}

ZTEST(agent_lin, test_mlmw_lin_checksum_enhanced)
{
	uint8_t pid = 0x24;
	uint8_t data[] = {0x01, 0x02, 0x03};
	uint8_t expected_checksum = 0x24;
	uint8_t checksum = mlmw_lin_checksum(pid, data, 3, true);
	EXPEC_EQ(checksum, expected_checksum);
}

ZTEST(agent_lin, test_mlmw_lin_checksum_enhanced_with_pid)
{
	uint8_t pid = 0x24;
	uint8_t data[] = {0x01, 0x02, 0x03};
	uint8_t expected_checksum = 0x24;
	uint8_t checksum = mlmw_lin_checksum(pid, data, 3, true);
	EXPEC_EQ(checksum, expected_checksum);
}

ZTEST(agent_lin, test_mlmw_lin_checksum_with_empty_data)
{
	uint8_t pid = 0x24;
	uint8_t data[] = {0x00};
	uint8_t expected_checksum = 0x25;
	uint8_t checksum = mlmw_lin_checksum(pid, data, 1, false);
	EXPEC_EQ(checksum, expected_checksum);
}

ZTEST(agent_lin, test_mlmw_lin_checksum_with_max_data)
{
	uint8_t pid = 0x24;
	uint8_t data[255] = {0};
	for (size_t i = 0; i < 255; i++) {
		data[i] = i;
	}
	uint8_t expected_checksum = 0x00;
	uint8_t checksum = mlmw_lin_checksum(pid, data, 255, false);
	EXPEC_EQ(checksum, expected_checksum);
}

ZTEST_SUITE(agent_lin, NULL, NULL, NULL, NULL, NULL);
